import{_ as n,o as i,c as t,a2 as r}from"./chunks/framework.vLhlLNVn.js";const g=JSON.parse('{"title":"Preise und Kosten","description":"","frontmatter":{"order":3,"adapter":"sourceanalytix","editLink":"https://github.com/DrozmotiX/ioBroker.sourceanalytix/edit/main/docs/de/02.anleitungen/03.preise-und-kosten.md"},"headers":[],"relativePath":"de/adapter/sourceanalytix/anleitungen/preise-und-kosten.md","filePath":"de/adapter/sourceanalytix/anleitungen/preise-und-kosten.md","lastUpdated":null}'),a={name:"de/adapter/sourceanalytix/anleitungen/preise-und-kosten.md"};function s(d,e,u,o,l,h){return i(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="preise-und-kosten" tabindex="-1">Preise und Kosten <a class="header-anchor" href="#preise-und-kosten" aria-label="Permalink to &quot;Preise und Kosten&quot;">​</a></h1><p><a id="costs-recalculated-change-price-change"></a></p><h2 id="werden-berechnete-kosten-neu-berechnet-wenn-ich-den-preis-andere-–-und-wie-andere-ich-ihn-ab-einem-datum" tabindex="-1">Werden berechnete Kosten neu berechnet, wenn ich den Preis ändere – und wie ändere ich ihn ab einem Datum? <a class="header-anchor" href="#werden-berechnete-kosten-neu-berechnet-wenn-ich-den-preis-andere-–-und-wie-andere-ich-ihn-ab-einem-datum" aria-label="Permalink to &quot;Werden berechnete Kosten neu berechnet, wenn ich den Preis ändere – und wie ändere ich ihn ab einem Datum?&quot;">​</a></h2><p><strong>Kurz:</strong> Nicht von selbst. Ein neuer Preis gilt ab dem Datum unter „Gültig ab&quot;, schon gebuchte Kosten bleiben, wie sie sind. Ab v0.7.0 kannst du sie mit der Aktion „Kosten ab Datum neu rechnen&quot; nachträglich neu berechnen lassen.</p><p>SourceAnalytix bucht Kosten fortlaufend: Mit jedem neuen Wert der Quelle rechnet es den Verbrauch seit dem letzten Wert mal den Preis, der in dieser Zeit galt, und addiert das zu den Kosten von Tag, Woche, Monat, Quartal und Jahr. Jeden Preis merkt es sich mit seinem Startzeitpunkt im State <code>sourceanalytix.0.priceHistory.&lt;Kategorie&gt;</code>. Darum ändert ein neuer Preis nichts an Kosten, die schon gebucht sind.</p><h3 id="preis-ab-einem-datum-andern-ab-v0-7-0" tabindex="-1">Preis ab einem Datum ändern (ab v0.7.0) <a class="header-anchor" href="#preis-ab-einem-datum-andern-ab-v0-7-0" aria-label="Permalink to &quot;Preis ab einem Datum ändern (ab v0.7.0)&quot;">​</a></h3><ol><li>Öffne die Instanz-Einstellungen von SourceAnalytix und dort den Tab „Preisdefinitionen&quot;.</li><li>Trage in der Zeile deines Tarifs bei „Preis pro Einheit&quot; den neuen Preis ein und bei „Gültig ab&quot; das Datum, ab dem er gilt. Das Datum darf in der Zukunft liegen.</li><li>Speichere. Der Adapter startet dabei neu.</li><li>Bis zum Datum rechnet SourceAnalytix mit dem alten Preis, ab 0:00 Uhr des Datums mit dem neuen. Beim Tageswechsel zeigt auch <code>sourceanalytix.0.priceDefinitions.&lt;Kategorie&gt;.currentPrice</code> den neuen Preis, im Log steht dann „Unit price for … changed from … to … (valid from date reached)&quot;.</li></ol><p>„Gültig ab&quot; gilt für den „Preis pro Monat&quot; genauso. Wechselst du den Anbieter, trägst du den neuen Preis in derselben Preisdefinition ein. So bleibt der Preisverlauf zusammen, und an den Quellen änderst du nichts.</p><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>Trage bei jeder Preisänderung auch ein neues Datum bei „Gültig ab&quot; ein. Lässt du das Datum der letzten Änderung stehen, ersetzt der neue Preis den alten im Preisverlauf ab diesem Datum. Ein Datum vor der letzten Preisänderung wirkt nur bis zu ihr, danach gilt wieder der spätere Preis. Ist „Gültig ab&quot; leer, gilt der neue Preis ab dem Speichern.</p><p><strong>Ab v0.7.0</strong> färbt der Dialog „Preis pro Einheit&quot;, „Preis pro Monat&quot; und „Gültig ab&quot; rot und zeigt „Preis geändert, „Gültig ab&quot; nicht …&quot;, sobald du einen Preis änderst, ohne das Datum anzupassen. Speichern geht trotzdem, falls du nur einen Tippfehler korrigierst. Nach dem Speichern steht zusätzlich eine Warnung im Log. Hast du den alten Preis versehentlich ersetzt: alten Preis wieder eintragen und speichern, danach den neuen Preis mit eigenem „Gültig ab&quot; eintragen und speichern.</p></div><h3 id="schon-gebuchte-kosten-neu-rechnen-ab-v0-7-0" tabindex="-1">Schon gebuchte Kosten neu rechnen (ab v0.7.0) <a class="header-anchor" href="#schon-gebuchte-kosten-neu-rechnen-ab-v0-7-0" aria-label="Permalink to &quot;Schon gebuchte Kosten neu rechnen (ab v0.7.0)&quot;">​</a></h3><p>Galt ein Preis schon früher, als du ihn eingetragen hast, setze bei „Gültig ab&quot; das richtige Datum und speichere. Öffne danach im Tab „Übersicht&quot; die Quelle und wähle die Aktion „Kosten ab Datum neu rechnen&quot; mit demselben Datum. Die Aktion gibt es nur bei Quellen mit „Kosten&quot;, und du startest sie für jede Quelle einzeln. Was sie genau tut und wo ihre Grenzen liegen, steht unter <a href="./zaehlerstaende-korrigieren#correct-wrong-too-high-negative">Kosten reparieren</a>.</p><p><strong>Bis v0.6.x:</strong> Es gibt keine Neuberechnung. Gebuchte Kosten bleiben beim alten Preis, auch in der laufenden Periode.</p><p><strong>Siehe auch:</strong> <a href="./../referenz/einstellungen#price-definition-structured-categories-base">Wie ist eine Preisdefinition aufgebaut?</a> · <a href="./../referenz/states-und-meldungen#prices-read-written-as-states">Wie werden Preise als States gelesen und geschrieben?</a></p><p><a id="include-monthly-base-fee"></a></p><h2 id="wie-rechne-ich-einen-monatlichen-grundpreis-ein" tabindex="-1">Wie rechne ich einen monatlichen Grundpreis ein? <a class="header-anchor" href="#wie-rechne-ich-einen-monatlichen-grundpreis-ein" aria-label="Permalink to &quot;Wie rechne ich einen monatlichen Grundpreis ein?&quot;">​</a></h2><p><strong>Kurz:</strong> Trage den Grundpreis in der Preisdefinition bei „Preis pro Monat&quot; ein und schalte bei der Quelle „Grundpreis einrechnen&quot; ein. „Kosten&quot; muss bei der Quelle ebenfalls an sein. Einen Jahresgrundpreis teilst du vorher durch 12.</p><p>SourceAnalytix bucht den Grundpreis als vollen Monatsbetrag am Ersten jedes Monats. Im ersten Monat bucht es ihn an dem Tag, ab dem der Preis gilt. Darum enthält der Monatswert den ganzen Grundpreis schon ab dem 1. Quartal und Jahr enthalten die Summe ihrer Monate. Tag und Woche enthalten ihn nur, wenn der Monatserste in ihnen liegt.</p><p>Ein Beispiel mit 12 € Grundpreis, gültig seit 1. Januar, am 15. März:</p><table tabindex="0"><thead><tr><th>Periode</th><th>Grundpreis darin</th></tr></thead><tbody><tr><td>Tag, Woche</td><td>0 €</td></tr><tr><td>Monat</td><td>12 €</td></tr><tr><td>Quartal</td><td>36 €</td></tr><tr><td>Jahr</td><td>36 €</td></tr></tbody></table><p>Trägst du den Grundpreis zum ersten Mal ohne „Gültig ab&quot; ein, gilt er ab dem 1. Januar des laufenden Jahres. Der Jahreswert enthält dann gleich alle Monate seit Januar.</p><h3 id="so-gehst-du-vor-ab-v0-7-0" tabindex="-1">So gehst du vor (ab v0.7.0) <a class="header-anchor" href="#so-gehst-du-vor-ab-v0-7-0" aria-label="Permalink to &quot;So gehst du vor (ab v0.7.0)&quot;">​</a></h3><ol><li>Trage in den Instanz-Einstellungen im Tab „Preisdefinitionen&quot; bei deinem Tarif den „Preis pro Monat&quot; ein und speichere. Der Adapter startet neu.</li><li>Bei einer neuen Quelle setzt du im Assistenten im Schritt „Preis&quot; den Haken „Grundpreis dieser Preisdefinition einrechnen&quot;.</li><li>Bei einer bestehenden Quelle setzt du in ihrer Detailansicht unter „Einstellungen&quot; den Haken „Grundpreis einrechnen&quot; und klickst auf „⚡ Übernehmen&quot;.</li><li>Prüfe den State <code>sourceanalytix.0.&lt;Gerät&gt;.currentYear.costs.03_currentMonth</code>. Er enthält jetzt den Grundpreis.</li></ol><h3 id="mehrere-quellen-mit-derselben-preisdefinition" tabindex="-1">Mehrere Quellen mit derselben Preisdefinition <a class="header-anchor" href="#mehrere-quellen-mit-derselben-preisdefinition" aria-label="Permalink to &quot;Mehrere Quellen mit derselben Preisdefinition&quot;">​</a></h3><p>Jede Quelle mit „Grundpreis einrechnen&quot; bucht den vollen Grundpreis. Gehören mehrere Quellen zu einem Anschluss, zum Beispiel Hausstrom und ein Unterzähler, zählt er sonst mehrfach. Schalte ihn dann nur bei einer Quelle ein.</p><p><strong>Ab v0.7.0</strong> weist SourceAnalytix an mehreren Stellen darauf hin (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1268" target="_blank" rel="noreferrer">#1268</a>):</p><ul><li>Der Assistent lässt den Haken aus, wenn eine andere Quelle derselben Preisdefinition den Grundpreis schon bucht, und zeigt „… bucht den Grundpreis dieser Preisdefinition bereits. Ist er hier auch an, zählt er doppelt.&quot;</li><li>Der Tab „Probleme&quot; zeigt „Grundpreis wird doppelt gebucht&quot; mit der Schaltfläche „Hier ausschalten&quot;.</li><li>Beim Start steht im Log <code>The basic fee of price definition &lt;Name&gt; is included by &lt;n&gt; sources … and is counted once per source</code>.</li></ul><p>Hat jede Quelle wirklich einen eigenen Anschluss mit eigenem Grundpreis, lass den Haken bei allen an.</p><p>Änderst du den Grundpreis, gilt „Gültig ab&quot; wie beim Preis pro Einheit, siehe <a href="#costs-recalculated-change-price-change">Preis ab einem Datum ändern</a>. Die Aktion „Kosten ab Datum neu rechnen&quot; rechnet den Grundpreis mit.</p><p><strong>Bis v0.6.x:</strong> Der Haken heißt „Inklusive Grundpreis&quot; und steht in den SourceAnalytix-Einstellungen am Datenpunkt unter „Berechnungseinstellungen&quot;.</p><p><strong>Siehe auch:</strong> <a href="./../referenz/einstellungen#price-definition-structured-categories-base">Wie ist eine Preisdefinition aufgebaut?</a> · <a href="./../fehlerbehebung/falsche-werte-und-bekannte-fehler#costs-stay-0-not-calculated">Kosten bleiben 0</a></p><p><a id="use-dynamic-electricity-price-tibber"></a></p><h2 id="wie-berucksichtige-ich-einen-dynamischen-strompreis-tibber-awattar" tabindex="-1">Wie berücksichtige ich einen dynamischen Strompreis (Tibber, Awattar)? <a class="header-anchor" href="#wie-berucksichtige-ich-einen-dynamischen-strompreis-tibber-awattar" aria-label="Permalink to &quot;Wie berücksichtige ich einen dynamischen Strompreis (Tibber, Awattar)?&quot;">​</a></h2><p><strong>Kurz:</strong> Stelle in der Preisdefinition die „Preisquelle&quot; auf „Datenpunkt&quot; und wähle bei „Preis-Datenpunkt&quot; den Datenpunkt mit dem aktuellen Preis. SourceAnalytix merkt sich jede Preisänderung mit ihrem Zeitpunkt und bewertet jeden Verbrauch mit dem Preis, der zu dieser Zeit galt.</p><h3 id="so-gehst-du-vor-ab-v0-7-0-1" tabindex="-1">So gehst du vor (ab v0.7.0) <a class="header-anchor" href="#so-gehst-du-vor-ab-v0-7-0-1" aria-label="Permalink to &quot;So gehst du vor (ab v0.7.0)&quot;">​</a></h3><ol><li>Öffne in den Instanz-Einstellungen den Tab „Preisdefinitionen&quot; und lege eine Zeile an oder ändere deine bestehende.</li><li>Wähle bei „Preisquelle&quot; „Datenpunkt&quot; und bei „Preis-Datenpunkt&quot; den Datenpunkt deines Strompreis-Adapters.</li><li>Speichere. Der Adapter startet neu und schreibt ins Log <code>Loaded unit price &lt;Preis&gt; for &lt;Kategorie&gt; from &lt;Datenpunkt&gt;</code>.</li><li>Ordne die Preisdefinition deinen Quellen zu, siehe <a href="#assign-prices-create-custom-tariffs">Wie ordne ich Preise zu?</a>.</li></ol><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>Der Datenpunkt muss den Preis in deiner Währung pro Einheit der Preisdefinition liefern, zum Beispiel <code>0.28</code> für 28 Cent pro kWh. SourceAnalytix multipliziert den Wert direkt mit dem Verbrauch. Liefert dein Adapter Cent, rechne ihn vorher um, etwa mit einem Alias.</p></div><p>Bei jeder Änderung des Datenpunkts steht im Log „Unit price for … changed from … to …&quot;. Hat er beim Start keinen gültigen Wert, warnt SourceAnalytix und rechnet bis zum ersten gültigen Preis mit dem zuletzt eingetragenen festen Preis, notfalls mit 0. Einen ungültigen neuen Wert ignoriert es und behält den bisherigen Preis.</p><h3 id="wie-die-kosten-aufgeteilt-werden" tabindex="-1">Wie die Kosten aufgeteilt werden <a class="header-anchor" href="#wie-die-kosten-aufgeteilt-werden" aria-label="Permalink to &quot;Wie die Kosten aufgeteilt werden&quot;">​</a></h3><p>Liegt zwischen zwei Werten der Quelle eine Preisänderung, teilt SourceAnalytix den Verbrauch nach der Zeit auf. Beispiel: Von 13:50 bis 14:10 Uhr wurde 1 kWh verbraucht, um 14:00 Uhr fällt der Preis von 0,30 € auf 0,20 €. Dann kostet die erste Hälfte 0,15 € und die zweite 0,10 €, zusammen 0,25 €. Je öfter deine Quelle sendet, desto genauer trifft das den echten Verbrauch.</p><h3 id="wo-die-kosten-gespeichert-werden" tabindex="-1">Wo die Kosten gespeichert werden <a class="header-anchor" href="#wo-die-kosten-gespeichert-werden" aria-label="Permalink to &quot;Wo die Kosten gespeichert werden&quot;">​</a></h3><ul><li>Die laufenden Kosten von Tag bis Jahr hält SourceAnalytix in <code>sourceanalytix.0.&lt;Gerät&gt;.dynamicCostMemory</code>. Nach einem Neustart rechnet es dort weiter und bewertet den bisherigen Verbrauch nicht mit dem aktuellen Preis neu.</li><li>Alle Preise mit Zeitpunkt stehen in <code>sourceanalytix.0.priceHistory.&lt;Kategorie&gt;</code>.</li><li>Den aktuellen Preis zeigt <code>sourceanalytix.0.priceDefinitions.&lt;Kategorie&gt;.currentPrice</code>.</li></ul><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>„Kosten ab Datum neu rechnen&quot; kennt nur den Verbrauch je Periode und verteilt ihn gleichmäßig über die Periode. Bei einem Preis, der sich stündlich ändert, ist das Ergebnis nur eine Näherung und meist ungenauer als die laufend gebuchten Kosten. Nimm die Aktion bei dynamischen Preisen nur, um einen Fehler zu beheben.</p></div><p><strong>Siehe auch:</strong> <a href="./../referenz/states-und-meldungen#prices-read-written-as-states">Wie werden Preise als States gelesen und geschrieben?</a> · <a href="./../fehlerbehebung/falsche-werte-und-bekannte-fehler#values-costs-far-too-high">Werte oder Kosten viel zu hoch</a></p><p><a id="bill-day-night-tariff"></a></p><h2 id="wie-rechne-ich-einen-tag-nachttarif-ht-nt-ab" tabindex="-1">Wie rechne ich einen Tag-/Nachttarif (HT/NT) ab? <a class="header-anchor" href="#wie-rechne-ich-einen-tag-nachttarif-ht-nt-ab" aria-label="Permalink to &quot;Wie rechne ich einen Tag-/Nachttarif (HT/NT) ab?&quot;">​</a></h2><p><strong>Kurz:</strong> Stelle in der Preisdefinition die „Preisquelle&quot; auf „Tarifumschaltung&quot;. Ein Datenpunkt schaltet dann zwischen zwei Preisen um, und SourceAnalytix bewertet den Verbrauch deines einen Zählers mit dem Preis, der gerade gilt. Den Verbrauch selbst teilt es nicht in HT und NT auf.</p><h3 id="so-gehst-du-vor-ab-v0-7-0-2" tabindex="-1">So gehst du vor (ab v0.7.0) <a class="header-anchor" href="#so-gehst-du-vor-ab-v0-7-0-2" aria-label="Permalink to &quot;So gehst du vor (ab v0.7.0)&quot;">​</a></h3><ol><li>Sorge für einen Umschalt-Datenpunkt, der während des einen Tarifs zum Beispiel <code>true</code> und sonst <code>false</code> ist. Die Uhrzeiten bringt SourceAnalytix nicht mit, den Datenpunkt setzt zum Beispiel ein Skript oder ein Zeitplan.</li><li>Wähle in den Instanz-Einstellungen im Tab „Preisdefinitionen&quot; bei „Preisquelle&quot; „Tarifumschaltung&quot;.</li><li>Trage bei „Preis pro Einheit&quot; den Preis ein, der gilt, wenn der Umschalt-Datenpunkt nicht aktiv ist, und bei „Aktiver Tarifpreis&quot; den Preis für den aktiven Zustand.</li><li>Wähle bei „Preis-Datenpunkt&quot; den Umschalt-Datenpunkt.</li><li>Speichere. Der Adapter startet neu.</li></ol><p>Wann der Datenpunkt als aktiv gilt:</p><table tabindex="0"><thead><tr><th>„Aktiver Auswahlwert&quot;</th><th>aktiv, wenn der Datenpunkt …</th></tr></thead><tbody><tr><td>eingetragen</td><td>genau diesen Wert hat, zum Beispiel <code>NT</code> oder <code>2</code></td></tr><tr><td>leer</td><td><code>true</code> ist, eine Zahl ungleich 0 oder ein Text außer <code>0</code>, <code>false</code>, <code>off</code>, <code>no</code>, <code>closed</code> und leer</td></tr></tbody></table><p>Jeder Wechsel kommt mit Zeitpunkt in den Preisverlauf, und im Log steht „Unit price for … changed from … to …&quot;. Liegt ein Wechsel zwischen zwei Werten der Quelle, teilt SourceAnalytix den Verbrauch nach der Zeit auf, wie unter <a href="#use-dynamic-electricity-price-tibber">dynamischer Strompreis</a> beschrieben.</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>Liefert dein Zähler eigene Zählerstände für HT und NT, kannst du stattdessen beide als eigene Quellen anlegen, jede mit einer Preisdefinition mit festem Preis. Dann hast du auch den Verbrauch je Tarif.</p></div><p>Den Verbrauch je Tarif aus einem Zähler auszuweisen, ist geplant (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1273" target="_blank" rel="noreferrer">#1273</a>).</p><p><strong>Siehe auch:</strong> <a href="./../referenz/einstellungen#price-definition-structured-categories-base">Wie ist eine Preisdefinition aufgebaut?</a></p><p><a id="assign-prices-create-custom-tariffs"></a></p><h2 id="wie-ordne-ich-preise-zu-und-lege-eigene-tarife-an-z-b-warmepumpe" tabindex="-1">Wie ordne ich Preise zu und lege eigene Tarife an (z. B. Wärmepumpe)? <a class="header-anchor" href="#wie-ordne-ich-preise-zu-und-lege-eigene-tarife-an-z-b-warmepumpe" aria-label="Permalink to &quot;Wie ordne ich Preise zu und lege eigene Tarife an (z. B. Wärmepumpe)?&quot;">​</a></h2><p><strong>Kurz:</strong> Einen Standardpreis gibt es nicht. Jede Quelle hat genau eine Preisdefinition. Für einen eigenen Tarif, etwa für die Wärmepumpe, legst du im Tab „Preisdefinitionen&quot; eine weitere Zeile an und wählst sie bei der Quelle aus.</p><h3 id="so-gehst-du-vor-ab-v0-7-0-3" tabindex="-1">So gehst du vor (ab v0.7.0) <a class="header-anchor" href="#so-gehst-du-vor-ab-v0-7-0-3" aria-label="Permalink to &quot;So gehst du vor (ab v0.7.0)&quot;">​</a></h3><ol><li>Öffne in den Instanz-Einstellungen den Tab „Preisdefinitionen&quot; und füge eine Zeile hinzu.</li><li>Trage bei „Kategorie&quot; einen eindeutigen Namen ein, zum Beispiel <code>Waermepumpe</code>. Unter diesem Namen wählst du den Tarif später aus.</li><li>Wähle die „Kostenart&quot; („Kosten&quot; für Bezug, „Erträge&quot; für Einspeisung), die „Einheit&quot;, in der gerechnet wird, die „Preisquelle&quot; und den „Preis pro Einheit&quot;, bei Bedarf auch „Preis pro Monat&quot;.</li><li>Speichere. Der Adapter startet neu.</li><li>Bei einer neuen Quelle wählst du den Tarif im Assistenten im Schritt „Preis&quot;. Wählbar sind nur Preisdefinitionen, deren Einheit zur Quelle passt.</li><li>Bei einer bestehenden Quelle wählst du ihn in der Detailansicht unter „Einstellungen&quot; bei „Preisdefinition&quot; und klickst auf „⚡ Übernehmen&quot;.</li></ol><p>Mehrere Quellen dürfen dieselbe Preisdefinition nutzen. Bucht sie einen Grundpreis, lies dazu <a href="#include-monthly-base-fee">Mehrere Quellen mit derselben Preisdefinition</a>. Alle Felder der Tabelle sind unter <a href="./../referenz/einstellungen#price-definition-structured-categories-base">Wie ist eine Preisdefinition aufgebaut?</a> erklärt.</p><h3 id="kosten-pro-kilometer-oder-in-einer-eigenen-einheit" tabindex="-1">Kosten pro Kilometer oder in einer eigenen Einheit <a class="header-anchor" href="#kosten-pro-kilometer-oder-in-einer-eigenen-einheit" aria-label="Permalink to &quot;Kosten pro Kilometer oder in einer eigenen Einheit&quot;">​</a></h3><p>Der Preis gilt immer pro Einheit der Preisdefinition. Für Kosten pro Kilometer wählst du die Einheit <code>km</code> und eine Quelle, die einen Kilometerstand in <code>km</code> oder <code>m</code> liefert. Ab v0.7.0 gibt es die Einheit <code>piece</code> für einen Preis pro Stück. Welche Einheiten es gibt, steht unter <a href="./../referenz/einstellungen#units-supported-energy-volume-weight">Welche Einheiten werden unterstützt?</a>.</p><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>Benenne eine Kategorie nicht um, solange Quellen sie nutzen. Die Quellen finden ihre Preisdefinition dann nicht mehr und rechnen nicht weiter. Im Log steht <code>Selected Type &lt;Name&gt; does not exist in Price Definitions</code>, im Tab „Probleme&quot; „Preisdefinition gibt es nicht mehr&quot;. Auch der Preisverlauf hängt am alten Namen. Wähle nach einer Umbenennung bei jeder Quelle die neue Preisdefinition.</p></div><p><strong>Bis v0.6.x:</strong> Die Tabelle der Preisdefinitionen steht ebenfalls in den Instanz-Einstellungen. Zugeordnet wird am Datenpunkt unter „Preisdefinition auswählen&quot;, siehe <a href="./../erste-schritte/erster-zaehler#configure-sourceanalytix-datapoint">Wo konfiguriere ich SourceAnalytix?</a>.</p><p><strong>Siehe auch:</strong> <a href="./quellen-und-einheiten#unit-datapoint-kwh-wh-m3">Welche Einheit stelle ich am Datenpunkt ein?</a> · <a href="./quellen-und-einheiten#track-pv-yield-feed-earnings">Wie erfasse ich PV-Ertrag, Einspeisung und Erlöse?</a></p>',65)])])}const b=n(a,[["render",s]]);export{g as __pageData,b as default};
